//! The short cue played when dictation turns on. The wavs are generated by tools/make_sounds.py and
//! compiled in, so there is nothing to install.

use windows::Win32::Media::Audio::{PlaySoundW, SND_ASYNC, SND_MEMORY, SND_NODEFAULT};
use windows::core::PCWSTR;

pub const NAMES: [&str; 10] = ["chime", "blip", "rise", "pluck", "bubble", "marimba", "glass", "sparkle", "pop", "soft"];

fn data(name: &str) -> Option<&'static [u8]> {
    Some(match name {
        "chime" => include_bytes!("../sounds/chime.wav"),
        "blip" => include_bytes!("../sounds/blip.wav"),
        "rise" => include_bytes!("../sounds/rise.wav"),
        "pluck" => include_bytes!("../sounds/pluck.wav"),
        "bubble" => include_bytes!("../sounds/bubble.wav"),
        "marimba" => include_bytes!("../sounds/marimba.wav"),
        "glass" => include_bytes!("../sounds/glass.wav"),
        "sparkle" => include_bytes!("../sounds/sparkle.wav"),
        "pop" => include_bytes!("../sounds/pop.wav"),
        "soft" => include_bytes!("../sounds/soft.wav"),
        _ => return None,
    })
}

/// Plays the named cue without blocking; "off" or an unknown name is silent.
pub fn play(name: &str) {
    if let Some(bytes) = data(name) {
        unsafe {
            let _ = PlaySoundW(PCWSTR(bytes.as_ptr() as *const u16), None, SND_MEMORY | SND_ASYNC | SND_NODEFAULT);
        }
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_listed_sound_is_a_wav() {
        for name in super::NAMES {
            let bytes = super::data(name).unwrap_or_else(|| panic!("{name} missing"));
            assert_eq!(&bytes[..4], b"RIFF", "{name}");
        }
    }
}
